overlap(i) = (MinList(high[i], high[i+1]) - MaxList(low[i], low[i+1])) / (high[i] - low[i]);
avgOverlap = average of overlap(i) for i in 0..overlapBars-2;
isLarge = average(high - low, overlapBars) >= sizeMultiple * average(high - low, longerLookback);
avgOverlap >= minOverlap && isLarge

level = highest(high, rangeLookback)[reentryWindow + 1];
brokeOut = any close[i] > level for i in 1..reentryWindow;
brokeOut && close[0] < level

// persistent, reset when the trend flag resets
runningHigh = max(runningHigh, high[0]);
if (high[0] < runningHigh) pullbackMax = max(pullbackMax, runningHigh - low[0]);
pullbackMax <= smallPullbackFraction * avgDailyRange

// persistent since the first leg's extreme
if (close[0] <= firstLegHigh - minRetraceFraction * firstLegHeight) noQualifyingPullback = false;
high[0] > firstLegHigh && noQualifyingPullback

// persistent: count, signalLow, minLowSince
if (close[0] > highest(high, resetLookback)[1]) { count = 0; }
else { minLowSince = min(minLowSince, low[0]);
  if (high[0] > high[1] && (count == 0 || minLowSince < signalLow)) { count = min(count + 1, 4); signalLow = low[0]; minLowSince = low[0]; justAdvanced = true; } }
count == countTarget && justAdvanced

spikeEnded = consecutive bull trend bars >= spikeBars ending at bar k;
firstPullbackSinceSpike = bar j (low[j] < low[j+1], no earlier such bar since k);
close[0] > high[j] && (j - 0) <= maxWaitBars

level = highest(high, breakoutLookback)[1] at bar k where close[k] > level;
failed = exists j in k-failBars..k-1 with close[j] < open[j] && close[j] < level;
barsSince(failed) >= blockBars

// long-side reading on a wedge TOP being faded short; mirrored on lows
late  = swingHigh(1, s) - swingHigh(2, s);
early = swingHigh(2, s) - swingHigh(3, s);
if perBar == 1 { late = late / barsBetween(swingHigh(1,s), swingHigh(2,s)); early = early / barsBetween(swingHigh(2,s), swingHigh(3,s)); }
isAccelerating = early > 0 && late > early * accelMultiple

correctionBars = currentBarIndex - barIndexOf(patternExtreme);
patternBars = barIndexOf(patternExtreme) - barIndexOf(firstPush);
correctionAdequate = correctionBars >= minCorrectionFraction * patternBars

flagHigh = highest(high, flagBars)[1]; flagLow = lowest(low, flagBars)[1];
brokeOut = requirePriorBreakout == 0 || (highest(high, priorBreakoutWindow)[1] > flagHigh);
isFinalFlagCandidate[1] && brokeOut && close[0] < flagLow

// long: target the pivotIndex-th most recent swing high
target = swingHigh(pivotIndex, swingStrength);
ctx.MarketPosition() > 0 && high[0] >= target

newSession = ctx.Date(0) != ctx.Date(1);
if (newSession) { barsIntoSession = 0; orHigh = high[0]; orLow = low[0]; orSet = false }
else { barsIntoSession = barsIntoSession + 1; if (!orSet) { orHigh = MaxList(orHigh, high[0]); orLow = MinList(orLow, low[0]) } }
if (!orSet && barsIntoSession >= openingBars - 1) orSet = true;
orHeight = orHigh - orLow;
return orSet

newSession = ctx.Date(0) != ctx.Date(1);
if (newSession) { push(sessionHigh - sessionLow) into dailyRanges; sessionHigh = high[0]; sessionLow = low[0] }
else { sessionHigh = MaxList(sessionHigh, high[0]); sessionLow = MinList(sessionLow, low[0]) }
adr = average(dailyRanges, dayLookback);
return count(dailyRanges) >= dayLookback

sessionAvgBarRange = sessionRangeSum / barsIntoSession;  /* both reset at the session date change */
stopDistance = stopMultiple * sessionAvgBarRange;
ctx.OpenPositionLoss() >= stopDistance * ctx.BigPointValue()

if (ctx.Date(0) != ctx.Date(1)) { trendFromOpen = 0; firstBarHigh = high[0]; firstBarLow = low[0] }
else {
  if (trendFromOpen == 0 && close[0] > firstBarHigh) trendFromOpen = 1;
  if (trendFromOpen == 0 && close[0] < firstBarLow) trendFromOpen = -1;
  if (trendFromOpen == 1 && close[0] < firstBarLow) trendFromOpen = 0;
  if (trendFromOpen == -1 && close[0] > firstBarHigh) trendFromOpen = 0
}
return trendFromOpen == 1

if (barsIntoSession == firstHourBars) {
  morningLegHeight = absvalue(close[0] - sessionOpen);
  if (morningLegHeight >= minLegAtr * WFSafe_AvgTrueRange(atrLength)) morningLegDirection = sign(close[0] - sessionOpen) else morningLegDirection = 0
}
return morningLegDirection == 1

if (ctx.Date(0) != ctx.Date(1)) tradesToday = 0;
if (ctx.MarketPosition() != 0 && ctx.MarketPosition(1) == 0) tradesToday = tradesToday + 1;
return tradesToday >= maxTradesPerDay

