// long-side reading = three pushes DOWN (a bull setup); pivots are confirmed SwingLow(swingStrength)
p1 = swingLow(3, swingStrength); p2 = swingLow(2, swingStrength); p3 = swingLow(1, swingStrength);
allWithinWindow = barsAgo(p1) <= lookbackBars;
extendsEnough = (p2 <= p1 - minPushExtensionTicks * tick) && (p3 <= p2 - minPushExtensionTicks * tick);
notTooFar = maxPushExtensionTicks == 0 || ((p1 - p2) <= maxPushExtensionTicks * tick && (p2 - p3) <= maxPushExtensionTicks * tick);
// shapeMode 0 = any shape (Brooks's own position), 1 = converging (wedge), 2 = diverging (expanding)
lowerLineSlope = slope(p1, p3); upperLineSlope = slope(swingHigh(2, swingStrength), swingHigh(1, swingStrength));
shapeOk = shapeMode == 0
  || (shapeMode == 1 && lowerLineSlope > upperLineSlope * convergenceMultiple)
  || (shapeMode == 2 && lowerLineSlope < upperLineSlope);
isThreePushPattern = allWithinWindow && extendsEnough && notTooFar && shapeOk

// minLegs alternating pivots, both sides pushing further out
expandingHighs = swingHigh(1, s) > swingHigh(2, s) && swingHigh(2, s) > swingHigh(3, s);
expandingLows  = swingLow(1, s)  < swingLow(2, s)  && swingLow(2, s)  < swingLow(3, s);
isExpandingTriangle = expandingHighs && expandingLows && pivotCountWithin(lookbackBars) >= minLegs
